            for j in range(i + 1, m):
                factor = A[j][i] / A[i][i]
                for k in range(n):
                    A[j][k] -= factor * A[i][k]
        return A

    def rank(A):
        rref = gaussian_elimination(A)
        if rref is None:
            return 0
        return sum(1 for row in rref if any(row))

